exercises.solution:
def eigenvector_2x2(m, lam):
    (a, b), (c, d) = m
    if abs(a - lam) > 1e-12 or abs(b) > 1e-12:
        v = (b, lam - a)
    else:
        v = (lam - d, c)
    if abs(v[0]) < 1e-12 and abs(v[1]) < 1e-12:
        v = (lam - d, c)
    n = (v[0] ** 2 + v[1] ** 2) ** 0.5
    if n < 1e-12:
        v = (1.0, 0.0)
        n = 1.0
    x, y = v[0] / n, v[1] / n
    if x < -1e-12 or (abs(x) < 1e-12 and y < 0):
        x, y = -x, -y
    return [round(x + 0.0, 6), round(y + 0.0, 6)]

