def fibonacci_matriks(n):
    def kali(a, b):
        return [[a[0][0] * b[0][0] + a[0][1] * b[1][0], a[0][0] * b[0][1] + a[0][1] * b[1][1]],
                [a[1][0] * b[0][0] + a[1][1] * b[1][0], a[1][0] * b[0][1] + a[1][1] * b[1][1]]]
    hasil = [[1, 0], [0, 1]]
    dasar = [[1, 1], [1, 0]]
    while n > 0:
        if n % 2 == 1:
            hasil = kali(hasil, dasar)
        dasar = kali(dasar, dasar)
        n //= 2
    return hasil[0][1]

