exercises.solution:
def distribusi_stasioner(P, langkah=500):
    n = len(P)
    pi = [1.0 / n] * n
    for _ in range(langkah):
        pi = [sum(pi[i] * P[i][j] for i in range(n)) for j in range(n)]
    return [round(x, 4) for x in pi]
